(function($){
  'use strict';

  const DATA_KEY = 'simpleRangeSlider';
  const DEFAULTS = {
    min: 0,
    max: 100,
    step: 1,
    range: false,
    values: null,
    disabled: false,
    slide: null,
    change: null
  };

  function clamp(value, min, max) {
    return Math.min(Math.max(value, min), max);
  }

  function alignToStep(value, step, min) {
    if (!step || step <= 0) {
      return value;
    }
    const stepsFromMin = Math.round((value - min) / step);
    return parseFloat((min + stepsFromMin * step).toFixed(5));
  }

  class RangeSlider {
    constructor($element, options) {
      this.$el = $element;
      this.options = $.extend({}, DEFAULTS, options);
      this._initValues();
      this._buildMarkup();
      this._bindEvents();
      this._refresh();
      this._applyDisabledState();
    }

    _initValues() {
      const { min, max, range } = this.options;
      const rawValues = this.options.values;
      if (range) {
        let values = Array.isArray(rawValues) && rawValues.length === 2 ? rawValues.slice(0, 2) : [min, max];
        values[0] = clamp(values[0], min, max);
        values[1] = clamp(values[1], min, max);
        if (values[0] > values[1]) {
          values = [values[1], values[0]];
        }
        this.currentValues = values;
      } else {
        const singleValue = clamp(rawValues != null ? rawValues : min, min, max);
        this.currentValues = [singleValue];
      }
    }

    _buildMarkup() {
      this.$el.empty();
      this.$el.addClass('ui-slider ui-slider-horizontal ui-widget ui-widget-content ui-corner-all');
      this.$range = $('<div>', {
        class: 'ui-slider-range ui-corner-all ui-widget-header'
      }).appendTo(this.$el);

      const handleClass = 'ui-slider-handle ui-corner-all ui-state-default';
      const handlesNeeded = this.options.range ? 2 : 1;
      this.$handles = [];
      for (let i = 0; i < handlesNeeded; i += 1) {
        const $handle = $('<span>', {
          class: handleClass,
          tabindex: 0
        }).appendTo(this.$el);
        $handle.css('touch-action', 'none');
        this.$handles.push($handle);
      }
    }

    _bindEvents() {
      this.$el.on('pointerdown.simpleSlider mousedown.simpleSlider touchstart.simpleSlider', (event) => {
        if (event.type === 'touchstart' && event.originalEvent.touches && event.originalEvent.touches.length) {
          event.pageX = event.originalEvent.touches[0].pageX;
          event.clientX = event.originalEvent.touches[0].clientX;
        }
        this._onTrackPointerDown(event);
      });
      this.$handles.forEach(($handle, index) => {
        $handle.on('pointerdown.simpleSlider mousedown.simpleSlider touchstart.simpleSlider', (event) => {
          event.stopPropagation();
          if (event.type === 'touchstart' && event.originalEvent.touches && event.originalEvent.touches.length) {
            event.pageX = event.originalEvent.touches[0].pageX;
            event.clientX = event.originalEvent.touches[0].clientX;
          }
          this._startDrag(event, index);
        });
        $handle.on('keydown.simpleSlider', (event) => {
          this._handleKeydown(event, index);
        });
      });
    }

    _onTrackPointerDown(event) {
      if (this.options.disabled) {
        return;
      }
      const index = this._closestHandleIndex(event);
      this._startDrag(event, index, true);
    }

    _closestHandleIndex(event) {
      if (this.$handles.length === 1) {
        return 0;
      }
      const eventX = event.pageX;
      let bestIndex = 0;
      let bestDistance = Infinity;
      this.$handles.forEach(($handle, index) => {
        const offset = $handle.offset();
        const center = offset.left + ($handle.outerWidth() / 2);
        const distance = Math.abs(center - eventX);
        if (distance < bestDistance) {
          bestDistance = distance;
          bestIndex = index;
        }
      });
      return bestIndex;
    }

    _startDrag(event, index, jumpToPosition = false) {
      if (this.options.disabled) {
        return;
      }
      event.preventDefault();
      this.draggingIndex = index;
      this.$el.addClass('ui-slider-dragging');
      this._bindDragEvents();
      if (jumpToPosition) {
        this._updateFromPointer(event, true);
      }
    }

    _bindDragEvents() {
      this._dragMove = (e) => this._updateFromPointer(e, true);
      this._dragEnd = (e) => {
        this._unbindDragEvents();
        this._trigger('change', e);
      };
      $(document)
        .on('pointermove.simpleSliderDrag mousemove.simpleSliderDrag touchmove.simpleSliderDrag', this._dragMove)
        .on('pointerup.simpleSliderDrag pointercancel.simpleSliderDrag mouseup.simpleSliderDrag touchend.simpleSliderDrag touchcancel.simpleSliderDrag', this._dragEnd);
    }

    _unbindDragEvents() {
      $(document)
        .off('pointermove.simpleSliderDrag mousemove.simpleSliderDrag touchmove.simpleSliderDrag', this._dragMove)
        .off('pointerup.simpleSliderDrag pointercancel.simpleSliderDrag mouseup.simpleSliderDrag touchend.simpleSliderDrag touchcancel.simpleSliderDrag', this._dragEnd);
      this.$el.removeClass('ui-slider-dragging');
      this.draggingIndex = null;
    }

    _updateFromPointer(event, triggerSlide) {
      let clientX = event.clientX;
      if (event.type && event.type.indexOf('touch') === 0) {
        const touch = event.originalEvent && (event.originalEvent.touches[0] || event.originalEvent.changedTouches && event.originalEvent.changedTouches[0]);
        if (touch) {
          clientX = touch.clientX;
        }
      } else if (clientX == null && event.pageX != null) {
        clientX = event.pageX;
      }
      if (clientX == null) {
        return;
      }
      const rect = this.$el[0].getBoundingClientRect();
      const position = clamp(clientX - rect.left, 0, rect.width);
      const ratio = rect.width === 0 ? 0 : position / rect.width;
      const rawValue = this.options.min + ratio * (this.options.max - this.options.min);
      const value = alignToStep(rawValue, this.options.step, this.options.min);
      this._setValue(this.draggingIndex, value, { triggerSlide, event });
    }

    _handleKeydown(event, index) {
      if (this.options.disabled) {
        return;
      }
      const keyHandlers = {
        ArrowLeft: -1,
        ArrowDown: -1,
        ArrowRight: 1,
        ArrowUp: 1,
        Home: 'min',
        End: 'max'
      };
      if (!(event.key in keyHandlers)) {
        return;
      }
      event.preventDefault();
      const action = keyHandlers[event.key];
      if (action === 'min') {
        this._setValue(index, this.options.min, { triggerSlide: true, event });
        this._trigger('change', event);
        return;
      }
      if (action === 'max') {
        this._setValue(index, this.options.max, { triggerSlide: true, event });
        this._trigger('change', event);
        return;
      }
      const stepDelta = this.options.step || 1;
      const currentValue = this.currentValues[index];
      const proposed = currentValue + (action * stepDelta);
      this._setValue(index, proposed, { triggerSlide: true, event });
      this._trigger('change', event);
    }

    _setValue(index, value, { triggerSlide = false, event = null } = {}) {
      if (index == null) {
        return;
      }
      const { min, max, range } = this.options;
      const normalized = clamp(alignToStep(value, this.options.step, min), min, max);
      const values = this.currentValues.slice();
      values[index] = normalized;
      if (range) {
        if (index === 0) {
          values[0] = Math.min(normalized, values[1]);
        } else {
          values[1] = Math.max(normalized, values[0]);
        }
      }
      const didChange = values.some((val, i) => val !== this.currentValues[i]);
      if (!didChange) {
        return;
      }
      this.currentValues = values;
      this._refresh();
      if (triggerSlide) {
        this._trigger('slide', event);
      }
    }

    _refresh() {
      const { min, max, range } = this.options;
      const scale = max - min || 1;
      const firstPercent = ((this.currentValues[0] - min) / scale) * 100;
      this.$handles[0].css('left', `${firstPercent}%`);
      if (range) {
        const secondPercent = ((this.currentValues[1] - min) / scale) * 100;
        this.$handles[1].css('left', `${secondPercent}%`);
        this.$range.css({ left: `${firstPercent}%`, width: `${Math.max(secondPercent - firstPercent, 0)}%` });
      } else {
        this.$range.css({ width: `${firstPercent}%` });
      }
      this._applyDisabledState();
    }

    _trigger(name, originalEvent) {
      const ui = {
        handle: this.draggingIndex != null ? this.$handles[this.draggingIndex][0] : null,
        value: this.currentValues[0],
        values: this.currentValues.slice()
      };
      if (typeof this.options[name] === 'function') {
        this.options[name].call(this.$el[0], originalEvent, ui);
      }
      this.$el.trigger(name, [ui]);
    }

    _applyDisabledState() {
      const disabled = !!this.options.disabled;
      this.$el
        .toggleClass('ui-state-disabled', disabled)
        .attr('aria-disabled', disabled);
      this.$handles.forEach(($handle) => {
        $handle
          .toggleClass('ui-state-disabled', disabled)
          .attr('tabindex', disabled ? -1 : 0);
      });
    }

    values(index, value) {
      if (typeof index === 'undefined') {
        return this.currentValues.slice();
      }
      if (typeof value === 'undefined') {
        return this.currentValues[index];
      }
      this._setValue(index, value, { triggerSlide: false });
      this._trigger('change', null);
    }

    value(newValue) {
      if (typeof newValue === 'undefined') {
        return this.currentValues[0];
      }
      if (Array.isArray(newValue) && this.options.range) {
        newValue.slice(0, 2).forEach((val, idx) => {
          this._setValue(idx, val, { triggerSlide: false });
        });
      } else {
        this._setValue(0, newValue, { triggerSlide: false });
      }
      this._trigger('change', null);
    }

    option(key, value) {
      if (typeof key === 'string') {
        this.options[key] = value;
      } else if ($.isPlainObject(key)) {
        this.options = $.extend({}, this.options, key);
      }
      this._initValues();
      this._refresh();
    }

    enable() {
      this.options.disabled = false;
      this._applyDisabledState();
    }

    disable() {
      this.options.disabled = true;
      this._applyDisabledState();
    }

    destroy() {
      this._unbindDragEvents();
      this.$el
        .removeClass('ui-slider ui-slider-horizontal ui-widget ui-widget-content ui-corner-all ui-slider-dragging')
        .off('.simpleSlider')
        .removeData(DATA_KEY)
        .removeAttr('aria-disabled')
        .empty();
      this.$handles.forEach(($handle) => {
        $handle.removeClass('ui-state-disabled').removeAttr('tabindex');
      });
      this.$handles = [];
    }
  }

  $.fn.slider = function(option, ...args) {
    if (typeof option === 'string') {
      let returnValue;
      this.each(function() {
        const instance = $.data(this, DATA_KEY);
        if (!instance || typeof instance[option] !== 'function') {
          return;
        }
        const result = instance[option](...args);
        if (returnValue === undefined && result !== undefined) {
          returnValue = result;
        }
      });
      return returnValue !== undefined ? returnValue : this;
    }

    return this.each(function() {
      const $this = $(this);
      let instance = $.data(this, DATA_KEY);
      const options = option || {};
      if (instance) {
        instance.option(options);
      } else {
        instance = new RangeSlider($this, options);
        $.data(this, DATA_KEY, instance);
      }
    });
  };
})(jQuery);
